async function togglePin(id){if(blocked||!S.r[id])return;if(S.pins.includes(id)){if(!await decide('Remove this record from protected evidence? Its ordinary detail may later roll into the disclosed summary window.'))return;S.pins=S.pins.filter(x=>x!==id);S.recent.push(id);}else{if(S.pins.length>=4){toast('Four selected places are full. Practice continues. Review and explicitly replace a selected record when ready.');return;}S.pins.push(id);}compact();save();if(S.route==='u3-work')renderWork();else renderPractice();}
