 function append(r,label,reason){if(!writtenRecord(r))return;const q=window.MathCatalogs.catalogs[r.catalog||window.MathCatalogs.current]?.questions[r.q]||Q[r.q];lines.push(label,q.prompt,q.expression||'');for(const a of r.a)lines.push('Attempt '+a[0]+': '+a[1]+' | '+outcome(a[2])+' | '+supports(a[3])+' | result version: '+(a[4]?.engine||'legacy/unknown'));if(r.d!==r.a.at(-1)?.[1])lines.push('Current draft (not checked): '+r.d);if(reason||r.reason)lines.push('My reasoning (retained for teacher review, not automatically assessed): '+(reason||r.reason));lines.push('');}
