function trigSetup(kind){const t=S.trig;if(kind==='angle')return{relationship:t.ratio||'',status:!t.ratio?'not_attempted':t.side==='BC'&&t.adjacent==='AB'&&t.hypotenuse==='AC'&&t.ratio==='tan'?'correct':'incorrect'};return{relationship:t.length||'',status:!t.length?'not_attempted':t.length==='sin'?'correct':'incorrect'};}
