function retainSetup(kind,setup,supportBefore){const t=S.trig;t.setupCount=Math.min(Number.MAX_SAFE_INTEGER,(t.setupCount||0)+1);const rows=t.setupAttempts||[];rows.push([t.setupCount,setup.relationship,setup.status==='correct'?'correct':'incorrect',supportBefore,{checker:TRIG_VERSION,instance:kind==='angle'?'abc-12-6-angle-a-v1':'right-30deg-h10-opposite-v1',relationship:setup.relationship,setup:setup.status,value:{status:'not_attempted'}}]);t.setupAttempts=rows.length>4?[rows[0],...rows.slice(-3)]:rows;State.recordSummary(S,'trig-setup',setup.status,supportBefore);}
